cypress_script:
describe('Challenging DOM Action Buttons', () => {
  it('should navigate to the page and click action buttons successfully', () => {
    cy.visit('https://the-internet.herokuapp.com/challenging_dom');
    cy.get('a.button').should('be.visible').click();
    cy.get('a.button.alert').should('be.visible').click();
    cy.get('a.button.success').should('be.visible').click();
  });

  it('should not change the URL or visibility of elements when clicking edit and delete', () => {
    cy.visit('https://the-internet.herokuapp.com/challenging_dom');
    cy.get('a[href="#edit"]').should('be.visible').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/challenging_dom');
    cy.get('a[href="#delete"]').should('be.visible').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/challenging_dom');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Challenging DOM Action Buttons', () => {
  test('should navigate to the page and click action buttons successfully', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/challenging_dom');
    await expect(page.locator('a.button')).toBeVisible();
    await page.locator('a.button').click();
    await expect(page.locator('a.button.alert')).toBeVisible();
    await page.locator('a.button.alert').click();
    await expect(page.locator('a.button.success')).toBeVisible();
    await page.locator('a.button.success').click();
  });

  test('should not change the URL or visibility of elements when clicking edit and delete', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/challenging_dom');
    await expect(page.locator('a[href="#edit"]')).toBeVisible();
    await page.locator('a[href="#edit"]').click();
    expect(page.url()).toBe('https://the-internet.herokuapp.com/challenging_dom');
    await expect(page.locator('a[href="#delete"]')).toBeVisible();
    await page.locator('a[href="#delete"]').click();
    expect(page.url()).toBe('https://the-internet.herokuapp.com/challenging_dom');
  });
});
